import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"46、【升】 巽下坤上","description":"周易尚氏学 - 46、【升】 巽下坤上","frontmatter":{"title":"46、【升】 巽下坤上","description":"周易尚氏学 - 46、【升】 巽下坤上"},"headers":[],"relativePath":"zh/classics/shangshi/051.md","filePath":"zh/classics/shangshi/051.md"}'),h={name:"zh/classics/shangshi/051.md"};function s(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_46、【升】-巽下坤上" tabindex="-1">46、【升】 巽下坤上 <a class="header-anchor" href="#_46、【升】-巽下坤上" aria-label="Permalink to “46、【升】 巽下坤上”">​</a></h1><p>阳遇阴则通。故名曰升。归藏曰称。牧誓称而戈。注称举也。又誉人曰称扬。升者升而上。举者亦扬之使上。故归藏曰称。周易曰升。其义并同。阳上升。故元亨。元谓乾元也。大人谓二。二为三所阻格。故不曰利见大人。而曰用见。言二宜升五也。坤为忧为恤。二升五大人得位。故曰勿恤。震为南。为征。三临群阴。故南征吉。左传成十六年。晋筮遇复。曰南国戚（左足）。以震为南。明夷九三曰南狩。亦以震为南。自震南象失传。清儒皆用虞氏法。以二升五互离为南。</p><p>彖曰。柔以时升。巽而顺。刚中而应。是以大亨。用见大人。勿恤。有庆也。南征吉。志行也。</p><p>二升五。故有庆。坤为志。三临重坤。故曰志行。</p><p>象曰。地中生木。升。君子以顺德。积小以高大。</p><p>巽为高为长。故为高大。坤为小为积。积小以高大者。言以坤阴柔顺之德。积累以成其高大也。象卦形也。</p><p>初六。允升。大吉。</p><p>允施氏作a 。说文同。云a 进也。晋六三云。众a 。即众进也。兹曰a 升。仍前进而升也。进遇阳。故大吉。</p><h3 id="象曰。允升大吉。上合志也。" tabindex="-1">象曰。允升大吉。上合志也。 <a class="header-anchor" href="#象曰。允升大吉。上合志也。" aria-label="Permalink to “象曰。允升大吉。上合志也。”">​</a></h3><p>上谓二三。九家谓上交。非。巽伏故为志。</p><p>九二。孚乃利用禴。无咎。</p><p>二孚五。五坤为吝啬。故曰抡。禴，夏日薄祭敢。兑为祭。巽为夏。故曰军乃利用抡。无咎矣。</p><h3 id="象曰。九二之孚。有喜也。" tabindex="-1">象曰。九二之孚。有喜也。 <a class="header-anchor" href="#象曰。九二之孚。有喜也。" aria-label="Permalink to “象曰。九二之孚。有喜也。”">​</a></h3><p>升五故有喜。</p><p>九三。升虚邑。</p><p>马云虎丘也。按左传僖二十八年。晋侯登有莘之虚。诗卫风升彼虚矣。虚者高丘。巽为高。故曰虚。坤为邑。升虚邑者。言升邑之高处也。正巽上象也。与同人九四之乘其庸。取象正同。荀爽作空虚解。后来诸家。以虚为坤象。多宗荀说。非。</p><h3 id="象曰。升虚邑。无所疑也。" tabindex="-1">象曰。升虚邑。无所疑也。 <a class="header-anchor" href="#象曰。升虚邑。无所疑也。" aria-label="Permalink to “象曰。升虚邑。无所疑也。”">​</a></h3><p>坤为迷为疑。阳遇阴。故无所疑。</p><p>六四。王用亨于歧山。吉。无咎。</p><p>震为王。兑为亨。震为陵为皈。而形上歧。故曰歧山。王用亨于歧山者。言望二升五。四得承阳。阴顺阳。犹臣事君。望二升五。犹望工至歧山。而有所亨献也。象曰顺事。顺承也。二若不升五。四如何得承阳哉。故望之也。此正文王服事殷之本旨。乃后儒谓文王作爻辞。不合自称为王。若为殷王。又无至歧山之理。以爻辞为周公作。此无讼易辞皆由象生。故韩宣子不谓为易辞。而曰易象。即只以人事言。纣尚能国文王。何不可到歧山。且文王于此事数言之。服事忠诚。溢于言表。又岂必实有其事。乃谓王为文王。无理甚矣。李过西谷易说云。若以此王为文王。则王用三驱。王假有庙。亦文王耶。驳旧说至详尽。</p><h3 id="象曰。王用亨于歧山。顺事也。" tabindex="-1">象曰。王用亨于歧山。顺事也。 <a class="header-anchor" href="#象曰。王用亨于歧山。顺事也。" aria-label="Permalink to “象曰。王用亨于歧山。顺事也。”">​</a></h3><p>坤为顺。言二升五。四得承阳。故曰顺事。</p><p>六五。贞吉。升阶。</p><p>贞吉。卜问吉也。坤为土为重。故有阶级之象。升阶言二升五也。五阳。故象曰大得志。</p><h3 id="象曰。贞吉升阶。大得志也。" tabindex="-1">象曰。贞吉升阶。大得志也。 <a class="header-anchor" href="#象曰。贞吉升阶。大得志也。" aria-label="Permalink to “象曰。贞吉升阶。大得志也。”">​</a></h3><p>坤为志。阳升五。故大得志</p><p>上六。冥升。利于不息之贞。</p><p>坤为晦冥为夜。故曰冥升。得阳应。故曰利于不息之贞。与利永贞同偕。盖上六为同性之四五所格。不能应三。故有此象。</p><h3 id="象曰。冥升在上。消不富也" tabindex="-1">象曰。冥升在上。消不富也 <a class="header-anchor" href="#象曰。冥升在上。消不富也" aria-label="Permalink to “象曰。冥升在上。消不富也”">​</a></h3><p>坤消故不富。</p>',30)])])}const m=e(h,[["render",s]]);export{_ as __pageData,m as default};
